Translate the following GNU C++ code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include<bits/stdc++.h>
using namespace std;

const int INF = 16843009;
int dist[15][15][15][15];
vector<vector<int>> capacity(400, vector<int>(400, 0));
string lab[20], req[20];
int dirx[] = {1,0,-1,0};
int diry[] = {0,1,0,-1};
int n, t;
int stamp = 3;
vector<int> mark(400, 0);
int reach[13][13], treach[13][13];

inline int node_id(int x,int y) { return (x-1)*n + y - 1; }

void expand(int val) {
    for (int i=1; i<=n; ++i)
        for (int j=1; j<=n; ++j)
            treach[i][j] = reach[i][j];
    for (int i=1; i<=n; ++i) {
        for (int j=1; j<=n; ++j) {
            if (treach[i][j] == val) {
                for (int k=0; k<4; ++k) {
                    int ni=i+dirx[k], nj=j+diry[k];
                    if (ni>0 && nj>0 && ni<=n && nj<=n && treach[ni][nj] < val && lab[ni][nj] != 'Y')
                        reach[ni][nj] = val;
                }
            }
        }
    }
}

bool canreach(int sx,int sy,int tx,int ty,int ix,int iy) {
    memset(reach,0,sizeof(reach));
    reach[sx][sy]=1;
    reach[ix][iy]=2;
    for (int it=0; it<100; ++it) {
        expand(1);
        if (reach[tx][ty]==1) return true;
        expand(2);
        if (reach[tx][ty]==2) return false;
    }
    return false;
}

int augment(int u,int sink,int bneck) {
    if (u == sink) return bneck;
    if (mark[u] == stamp) return 0;
    mark[u] = stamp;
    for (int v=sink; v>=0; --v) {
        if (capacity[u][v] > 0) {
            int got = augment(v, sink, min(bneck, capacity[u][v]));
            if (got) {
                capacity[u][v] -= got;
                capacity[v][u] += got;
                return got;
            }
        }
    }
    return 0;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    fill(&dist[0][0][0][0], &dist[0][0][0][0] + 15*15*15*15, INF);
    cin >> n >> t;
    int infx=0, infy=0;
    for (int i=1; i<=n; ++i) {
        string s;
        cin >> s;
        lab[i] = " " + s;
        for (int j=1; j<=n; ++j) {
            dist[i][j][i][j] = 0;
            if (lab[i][j] == 'Z') { infx=i; infy=j; }
        }
    }
    for (int i=1; i<=n; ++i) {
        string s;
        cin >> s;
        req[i] = " " + s;
    }
    for (int i=1; i<=n; ++i)
        for (int j=1; j<=n; ++j)
            for (int d=0; d<4; ++d) {
                int ni=i+dirx[d], nj=j+diry[d];
                if (ni>0 && ni<=n && nj>0 && nj<=n && lab[i][j]!='Y' && lab[ni][nj]!='Y')
                    dist[i][j][ni][nj] = 1;
            }
    for (int kx=1; kx<=n; ++kx)
        for (int ky=1; ky<=n; ++ky)
            for (int sx=1; sx<=n; ++sx)
                for (int sy=1; sy<=n; ++sy)
                    for (int tx=1; tx<=n; ++tx)
                        for (int ty=1; ty<=n; ++ty)
                            dist[sx][sy][tx][ty] = min(dist[sx][sy][tx][ty],
                                                       dist[sx][sy][kx][ky] + dist[kx][ky][tx][ty]);
    int src = 2*n*n + 1, sink = 2*n*n + 2;
    for (int i=1; i<=n; ++i)
        for (int j=1; j<=n; ++j) {
            if (isdigit(lab[i][j])) capacity[src][node_id(i,j)] = lab[i][j]-'0';
            if (isdigit(req[i][j])) capacity[n*n + node_id(i,j)][sink] = req[i][j]-'0';
            if (isdigit(lab[i][j])) {
                for (int a=1; a<=n; ++a)
                    for (int b=1; b<=n; ++b) {
                        if (lab[i][j] > '0' && req[a][b] > '0' && isdigit(req[a][b]) &&
                            dist[i][j][a][b] <= t && canreach(i,j,a,b,infx,infy))
                            capacity[node_id(i,j)][n*n + node_id(a,b)] = 1000;
                    }
            }
        }
    int flow=0, add;
    while ((add = augment(src,sink,1000)) > 0) {
        flow += add;
        ++stamp;
    }
    cout << flow << '\n';
    return 0;
}
